stdlib/fs/fs.kav:
use std.fs

/// Why a file operation failed.
pub type FsError = NotFound(path: String) | Denied(path: String) | Failed(path: String, reason: String)

/// What kind of thing a path names.
pub type FileKind = File | Folder | Link

/// What is at a path (`fs.info`).
pub type FileInfo {
    pub kind: FileKind
    /// In bytes; 0 for a folder.
    pub size: Int
    /// When it last changed: a moment, in milliseconds since 1970 (14.4).
    pub modified_ms: Int
    /// Whether the owner may not write it.
    pub read_only: Bool
    /// The Unix permission bits, such as `0o644`.
    pub permissions: Int
}

/// What is at `path`: its kind, size, last change and permissions. A
/// link is described itself, not what it points to.
pub fn info(path: String) -> FileInfo ! FsError uses Fs.read { … }

/// A file being written piece by piece (`fs.create_writer`, spec 14.3).
/// Let go before `finish`, its file is deleted.
pub type FileWriter: Drop {
    id: Int

    /// Adds `data` at the end of the file.
    pub fn write(self, data: Bytes) ! FsError uses Fs.write { … }

    /// Adds `text` at the end of the file, as UTF-8.
    pub fn write_text(self, text: String) ! FsError uses Fs.write { … }

    /// Writes what is gathered, closes the file, and gives how many bytes
    /// it holds; with `sync`, they are on the disk before it returns.
    pub fn finish(self, sync: Bool = false) -> Int ! FsError uses Fs.write { … }

    fn drop(self) uses Fs.write { … }
}

/// A new, empty file at `path` (one there is emptied), written piece by
/// piece as its data comes.
pub fn create_writer(path: String) -> FileWriter ! FsError uses Fs.write { … }

/// What happened to a watched path (spec 14.3).
pub type ChangeKind = Created | Changed | Removed

/// A change to a watched file or folder: the path, under the watched
/// path as it was written, and what happened to it.
pub type FileChange {
    pub path: String
    pub kind: ChangeKind
}

/// A file or folder watched for changes (`fs.watch`, spec 14.3).
pub type Watcher: Drop {
    id: Int

    /// The next change, waiting for one; `none` once it is closed.
    pub fn next(self) -> FileChange? uses Fs.read { … }

    /// The changes since the last call, each path once, without waiting.
    pub fn poll(self) -> [FileChange] uses Fs.read { … }

    /// Stops watching.
    pub fn close(self) { … }

    fn drop(self) { … }
}

/// Watches the file at `path`, or the folder and everything in it.
pub fn watch(path: String) -> Watcher ! FsError uses Fs.read { … }

/// A change from the runtime's row: its kind's digit, a space, the path.
fn change_of(row: String) -> FileChange
    require row.len() >= 2
    example change_of("0 a/b.txt") == FileChange(path: "a/b.txt", kind: ChangeKind.Created)
    example change_of("2 x") == FileChange(path: "x", kind: ChangeKind.Removed)
{ … }

stdlib/gpu/gpu.kav:
use std.gpu

use std.math

use std.window

/// Why there is nothing to draw into: no GPU, a window that can't be
/// drawn into, or a frame that can't be had now.
pub type GpuError = Unavailable(reason: String) | BadTexture(reason: String)

/// What draws into a window.
pub type Screen: Drop {
    id: Int
    window: Int

    /// The next picture to draw, as big as the window is now; it waits for
    /// the screen's next refresh when the last picture isn't shown yet.
    pub fn frame(self) -> Frame ! GpuError uses Window { … }

    fn drop(self) uses Window { … }
}

/// A picture being drawn. One not shown before its last holder ends is
/// thrown away.
pub type Frame: Drop {
    id: Int

    /// Fills the picture with one color, each part from 0 to 1.
    pub fn clear(self, r: Float32, g: Float32, b: Float32) uses Window
        require r >= 0.0 and r <= 1.0 and g >= 0.0 and g <= 1.0 and b >= 0.0 and b <= 1.0
    { … }

    /// Draws `vertices`, three to a triangle, through `pipeline`: once for
    /// each of `instances` when its vertex fn takes an instance, with
    /// `shared` given to every corner when it takes one, `textures` to its
    /// fragment fn (spec 15.3), and the vertices by their place in
    /// `indices` when given, three to a triangle.
    pub fn draw<V, I, S, T>(self, pipeline: Pipeline<V, I, S, T>, vertices: [V], instances: [I] = [], shared: S? = none, textures: [Texture] = [], indices: [UInt32]? = none) uses Window { … }

    /// Puts the picture on the screen.
    pub fn show(self) uses Window { … }

    fn drop(self) uses Window { … }
}

/// What draws into the window `win`, using the program's GPU.
pub fn screen(win: AppWindow) -> Screen ! GpuError uses Window { … }

/// What a pipeline's vertex fn doesn't take: an instance, or a value
/// shared by the draw (spec 15.3).
pub type NoInput {
}

/// A picture on the GPU for fragment fns to read (spec 15.3). Its pixels
/// are kept here too, so `sample` gives the same colors on the CPU.
pub type Texture: Drop {
    id: Int
    pub width: Int
    pub height: Int
    pixels: [UInt8]

    /// Made from a KTX2 file's compressed blocks, which only the GPU reads:
    /// it has no pixels here.
    compressed: Bool = false

    invariant width >= 1 and width <= 8192 and height >= 1 and height <= 8192
    invariant compressed or pixels.len() == width * height * 4

    /// The color at `u` (0 left, 1 right) and `v` (0 top, 1 bottom),
    /// blended between the four nearest pixels, as the GPU blends them.
    pub fn sample(self, u: Float32, v: Float32) -> (Float32, Float32, Float32, Float32)
        require not self.compressed
    { … }

    /// Part `k` of the pixel at `x`, `y` (the nearest edge pixel when it
    /// is past one): a color made linear from sRGB, as the GPU reads it,
    /// or the opacity.
    fn part(self, x: Int, y: Int, k: Int) -> Float
        require not self.compressed and k >= 0 and k <= 3
    { … }

    fn drop(self) uses Window { … }
}

/// A picture for fragment fns to read (spec 15.3): `pixels` are four for
/// each pixel (red, green, blue and opacity, in sRGB), row by row from
/// the top.
pub fn texture(width: Int, height: Int, pixels: [UInt8]) -> Texture ! GpuError uses Window
    require width >= 1 and width <= 8192 and height >= 1 and height <= 8192 and pixels.len() == width * height * 4
{ … }

/// A texture of the compressed blocks in a KTX2 file's bytes (BC1 to BC7
/// on desktops, ASTC 4×4 on phones), given to the GPU as they are. Only
/// the GPU reads it: `sample` it in a `gpu fragment fn`.
pub fn compressed_texture(file: Bytes) -> Texture ! GpuError uses Window { … }

