    require codes.len() == 257
{ … }

/// A symbol's Huffman code: its bits, and how many.
type Code {
    bits: Int
    length: Int
}

/// Each byte's Huffman code, from the canonical tables `huffman` decodes
/// with: the codes of one length are consecutive, in symbol order.
