/// What `receive.take()` gives: the next value, or `Closed` once the
/// channel is closed and empty. A `none` sent on a `Channel<T?>` is
/// `Item(value: none)`, never `Closed` (decision 0097).
pub type Taken<T> = Item(value: T) | Closed

stdlib/tensor/tensor.kav:
use std.matrix

/// Numbers in `shape.len()` dimensions: `items` holds them, the last
/// dimension's next to each other.
pub type Tensor<T: Number>: Add, Sub, Mul, MatMul {
    pub shape: [Int]
    pub items: [T]

    /// How many numbers it holds.
    pub fn len(self) -> Int { … }

    /// How many dimensions it has.
    pub fn rank(self) -> Int { … }

    /// The number at `at`, one index per dimension.
    pub fn get(self, at: [Int]) -> T
        require at.len() == self.shape.len()
    { … }

    /// The same numbers in another shape with as many of them.
    pub fn reshape(self, shape: [Int]) -> Tensor<T> { … }

    /// The last two dimensions swapped.
    pub fn transpose(self) -> Tensor<T>
        require self.shape.len() >= 2
    { … }

    /// The sum of every number, added in order.
    pub fn sum(self) -> T { … }

    /// The largest number, or `none` when it has none.
    pub fn max(self) -> T? { … }

    /// Each number through `f`.
    pub fn map(self, f: fn(T) -> T) -> Tensor<T> { … }

    /// Each number times `k`.
    pub fn scale(self, k: T) -> Tensor<T> { … }

    pub fn add(self, other: Tensor<T>) -> Tensor<T> { … }

    pub fn sub(self, other: Tensor<T>) -> Tensor<T> { … }

    pub fn mul(self, other: Tensor<T>) -> Tensor<T> { … }

    /// `a @ b`: the matrix product of the last two dimensions, for each of
    /// the others, which must match.
    pub fn matmul(self, other: Tensor<T>) -> Tensor<T> { … }

    /// `a op b` item by item; the shapes must be the same.
    fn each(self, other: Tensor<T>, op: String, f: fn(T, T) -> T) -> Tensor<T> { … }
}

/// How many numbers a tensor of `shape` holds; `none` for a negative
/// size, or a count too big for an `Int`.
fn count(shape: [Int]) -> Int? { … }

/// A tensor of `shape`, every number `value`.
pub fn full<T: Number>(shape: [Int], value: T) -> Tensor<T>
    require count(shape) != none
{ … }

/// A tensor of `shape`, every number 0.
pub fn zeros<T: Number>(shape: [Int]) -> Tensor<T> { … }

/// A tensor of `shape`, every number 1.
pub fn ones<T: Number>(shape: [Int]) -> Tensor<T> { … }

/// A tensor of one dimension holding `items`.
pub fn of<T: Number>(items: [T]) -> Tensor<T> { … }

/// A tensor of two dimensions from its rows, each as long.
pub fn of_rows<T: Number>(rows: [[T]]) -> Tensor<T> { … }

stdlib/term/term.kav:
use std.io

/// `s` between the escape codes `open` and `close` when `on`, else `s`.
/// A `close` inside `s`, from a nested style of the same kind, opens this
/// style again, so the rest of `s` keeps it.
fn paint(s: String, open: Int, close: Int, on: Bool) -> String
    example paint("hi", 31, 39, false) == "hi"
    example paint("hi", 31, 39, true) == "\u{1B}[31mhi\u{1B}[39m"
    example paint("a\u{1B}[39mb", 31, 39, true) == "\u{1B}[31ma\u{1B}[39m\u{1B}[31mb\u{1B}[39m"
{ … }

/// `s` in color `code`, ended with the default color (39).
fn color(s: String, code: Int) -> String uses Console { … }

/// `s` in black.
pub fn black(s: String) -> String uses Console { … }

/// `s` in red.
pub fn red(s: String) -> String uses Console { … }

/// `s` in green.
pub fn green(s: String) -> String uses Console { … }

/// `s` in yellow.
pub fn yellow(s: String) -> String uses Console { … }

/// `s` in blue.
pub fn blue(s: String) -> String uses Console { … }

/// `s` in magenta.
pub fn magenta(s: String) -> String uses Console { … }

/// `s` in cyan.
pub fn cyan(s: String) -> String uses Console { … }

/// `s` in white.
pub fn white(s: String) -> String uses Console { … }

/// `s` in gray.
pub fn gray(s: String) -> String uses Console { … }

/// `s` in bold.
pub fn bold(s: String) -> String uses Console { … }

/// `s` faint.
pub fn dim(s: String) -> String uses Console { … }

/// `s` in italics.
pub fn italic(s: String) -> String uses Console { … }

/// `s` underlined.
pub fn underline(s: String) -> String uses Console { … }

/// A progress bar (spec 14.13): the job's size, the steps done, and the
/// percentage drawn last (-1 before the first).
pub type Progress {
    total: Int
    steps: Int
    shown: Int

    invariant total >= 0 and total <= 1_000_000_000_000
    invariant steps >= 0 and steps <= total
    invariant shown >= -1 and shown <= 100

    /// `n` more steps of the job are done: the bar is drawn again. Steps
    /// past the job's size leave it full.
    pub fn step(self, n: Int) -> Progress uses Console
        require n >= 0 and n <= 1_000_000_000_000
    { … }

    /// The job is over: the bar is drawn full and its line ends.
    pub fn done(self) uses Console { … }
}

/// How much of `total` steps `done` is, in whole percent (100 for a job
/// of no steps).
fn percent_of(done: Int, total: Int) -> Int
    require total >= 0 and total <= 1_000_000_000_000
    require done >= 0 and done <= 1_000_000_000_000
    example percent_of(6, 10) == 60
    example percent_of(15, 10) == 100
    example percent_of(0, 0) == 100
{ … }

/// The bar for `done` of `total` steps, `width` marks wide:
/// `[############--------]  60%  6/10`.
fn bar_text(done: Int, total: Int, width: Int) -> String
    require total >= 0 and total <= 1_000_000_000_000
    require done >= 0 and done <= 1_000_000_000_000
    require width >= 1 and width <= 200
    example bar_text(6, 10, 20) == "[############--------]  60%  6/10"
    example bar_text(1, 3, 4) == "[#---]  33%  1/3"
    example bar_text(0, 0, 4) == "[####] 100%  0/0"
{ … }

/// Draws `bar` on its line again, when its percentage changed and output
/// is a terminal.
fn draw(bar: Progress) -> Progress uses Console { … }

/// A progress bar for a job of `total` steps, drawn at 0%.
pub fn progress(total: Int) -> Progress uses Console
    require total >= 0 and total <= 1_000_000_000_000
{ … }

/// Prints `question` and a space, and gives the line typed, or `none` at
/// the end of input.
pub fn prompt(question: String) -> String? uses Console { … }

/// Asks for a whole number until the answer is one; `none` at the end
/// of input.
pub fn prompt_int(question: String) -> Int? uses Console { … }

/// Asks for a number until the answer is one; `none` at the end of input.
pub fn prompt_float(question: String) -> Float? uses Console { … }

/// A password or a token, as `term.prompt_secret` gives it: `text` is a
/// `secret` field, kept out of `print` and logs (spec 8.7).
pub type Secret {
    pub secret text: String
}

/// Asks for a password or a token, the typing not shown; `none` at the
/// end of input.
pub fn prompt_secret(question: String) -> Secret? uses Console { … }

/// `true` for a yes, `false` for a no, `none` for anything else.
fn yes_no(answer: String) -> Bool?
    example yes_no(" Yes ") == true
    example yes_no("n") == false
    example yes_no("") == none
{ … }

/// Asks a yes-or-no question; anything but a yes or a no gives
/// `default`.
pub fn confirm(question: String, default: Bool) -> Bool uses Console { … }

/// Prints `question` and `options`, numbered from 1, and gives the index
/// (from 0) of the one chosen, or `none` for an answer that is not one.
pub fn choose(question: String, options: [String]) -> Int? uses Console { … }

stdlib/test/test.kav:
/// A type that makes its own values for generated tests: whenever
/// `kavach test` needs a value of the type, it calls `sample`.
pub interface Sample {
    fn sample(gen: Gen) -> Self
}

/// Random choices for `sample`. They are the test run's, seeded, never
/// the real world's: real random numbers need the `Random` capability.
pub type Gen {
    /// A whole number from `from` to `to`, both included.
    pub fn int(self, from: Int, to: Int) -> Int
        require from <= to
        require from >= 0 or to <= 9_223_372_036_854_775_807 + from
        ensure result >= from and result <= to
        example Gen().int(3, 3) == 3
    { … }

    /// `true` or `false`.
    pub fn bool(self) -> Bool { … }

    /// One of `items`.
    pub fn pick<T>(self, items: [T]) -> T
        require not items.is_empty()
        example Gen().pick([7]) == 7
    { … }

    /// A word of 1 to 8 lowercase letters.
    pub fn word(self) -> String
        ensure result.len() >= 1 and result.len() <= 8
    { … }
}

stdlib/text/text.kav:
/// Whether `c` is one of the digits 0 to 9.
fn is_digit(c: Char) -> Bool
    example is_digit('7')
    example not is_digit('x')
{ … }

/// Whether `c` is a letter or digit of the Latin alphabet.
fn is_word(c: Char) -> Bool
    example is_word('Q')
    example is_word('é')
    example not is_word('-')
{ … }

/// The numbers written in `s`, as text: each run of digits, with one
/// `.` and more digits when `fraction` is set, and a `-` just before it
/// unless that `-` follows a letter or digit (`item-3` is a name).
fn number_texts(s: String, fraction: Bool) -> [String]
    example number_texts("x -1.5 and 2", true) == ["-1.5", "2"]
    example number_texts("a-1.5", false) == ["1", "5"]
{ … }

/// Every whole number written in `s`, in order (`"a12b-3"` gives
/// `[12, -3]`). A comma or any other mark ends a number, and one too big
/// for `Int` is left out. Unlike `Int(s)`, which reads the whole text
/// strictly (spec 2.1), this looks for numbers inside other text.
pub fn find_ints(s: String) -> [Int]
    example find_ints("a12b34") == [12, 34]
    example find_ints("pages 10-20") == [10, 20]
    example find_ints("none here") == []
{ … }

/// The first whole number written in `s`, as `find_ints` reads them, or
/// `none` when there is none.
pub fn find_int(s: String) -> Int?
    example find_int("12sdsfs") == 12
    example find_int("sd23") == 23
    example find_int("sd3f") == 3
    example find_int("-5 °C") == -5
    example find_int("item-3") == 3
    example find_int("₹1,299") == 1
    example find_int("no digits") == none
{ … }

/// The first number written in `s`, with a fraction if it has one
/// (`"v2.5b"` is 2.5, `"x3"` is 3.0), or `none` when there is none.
pub fn find_float(s: String) -> Float?
    example find_float("pi is 3.14!") == 3.14
    example find_float("x3") == 3.0
    example find_float("-0.5 m") == -0.5
    example find_float("end.") == none
{ … }

stdlib/time/digits.kav:
/// `n` as text of at least `width` digits, with zeros in front.
pub fn padded(n: Int, width: Int) -> String
    require n >= -1_000_000_000 and n <= 1_000_000_000
    require width >= 1 and width <= 20
    example padded(7, 2) == "07"
    example padded(2026, 4) == "2026"
    example padded(-5, 3) == "-005"
{ … }

/// The whole number `text` writes in exactly `width` digits, with no sign
/// and no spaces: `Int(text)` takes both.
pub fn read(text: String, width: Int) -> Int?
    require width >= 1 and width <= 9
    example read("07", 2) == 7
    example read("+7", 2) == none
    example read("7", 2) == none
    example read("a7", 2) == none
{ … }

/// How many seconds ahead of UTC the offset `+05:30` is, if `text` is one;
/// it may have seconds, `+05:21:10`.
pub fn offset(text: String) -> Int?
    example offset("+05:30") == 19_800
    example offset("-08:00") == -28_800
    example offset("+05:21:10") == 19_270
    example offset("05:30") == none
    example offset("+24:00") == none
    example offset("+5:30") == none
    example offset("Asia/Kolkata") == none
{ … }

/// An offset of `seconds` as text: `+05:30`, and `Z` for none.
pub fn offset_text(seconds: Int) -> String
    require seconds > -86_400 and seconds < 86_400
    example offset_text(19_800) == "+05:30"
    example offset_text(-28_800) == "-08:00"
    example offset_text(19_270) == "+05:21:10"
    example offset_text(0) == "Z"
{ … }

stdlib/time/time.kav:
use std.time

use std.time.digits

/// A length of time, in milliseconds. Written with a unit after a whole
/// number: `200.ms`, `5.seconds`, `2.minutes`, `1.hours`, `3.days`.
/// Durations add, subtract, scale by a whole number and compare (2.16).
pub type Duration: Add, Sub, Mul<Int>, Comparable {
    pub ms: Int

    /// `a + b`: the two lengths together.
    pub fn add(self, other: Duration) -> Duration
        require self.ms >= -1_000_000_000_000_000 and self.ms <= 1_000_000_000_000_000
        require other.ms >= -1_000_000_000_000_000 and other.ms <= 1_000_000_000_000_000
        example (2.seconds + 500.ms).ms == 2500
    { … }

    /// `a - b`: what is left of `a` after `b`; below 0 when `b` is longer.
    pub fn sub(self, other: Duration) -> Duration
        require self.ms >= -1_000_000_000_000_000 and self.ms <= 1_000_000_000_000_000
        require other.ms >= -1_000_000_000_000_000 and other.ms <= 1_000_000_000_000_000
        example (1.minutes - 15.seconds).ms == 45_000
    { … }

    /// `d * n`: `n` times as long.
    pub fn mul(self, other: Int) -> Duration
        require self.ms >= -1_000_000_000_000_000 and self.ms <= 1_000_000_000_000_000
        require other >= -1_000_000_000_000_000 and other <= 1_000_000_000_000_000
        require other == 0 or self.ms.abs() <= 1_000_000_000_000_000 / other.abs()
        example (250.ms * 4).ms == 1000
    { … }

    /// `a < b` and the others: the shorter comes first.
    pub fn compare(self, other: Duration) -> Int
        example 90.seconds.compare(2.minutes) < 0
    { … }
}

/// A day of the week.
pub type Weekday = Monday | Tuesday | Wednesday | Thursday | Friday | Saturday | Sunday

/// Why text isn't a date or a time.
pub type DateError = Invalid(text: String)

/// A day of the calendar, with no time and no zone: months 1 to 12, days
/// 1 to the month's last. The calendar is the Gregorian one, for every
/// year, with no exceptions (spec 14.4).
pub type Date {
    pub year: Int
    pub month: Int
    pub day: Int

    invariant year >= -1_000_000 and year <= 1_000_000
    invariant month >= 1 and month <= 12
    invariant day >= 1 and day <= days_in_month(year, month)

    /// The day of the week.
    pub fn weekday(self) -> Weekday
        example Date(year: 2024, month: 1, day: 31).weekday() == Weekday.Wednesday
        example Date(year: 1970, month: 1, day: 1).weekday() == Weekday.Thursday
    { … }

    /// The date `n` days later (or earlier, for a negative `n`).
    pub fn add_days(self, n: Int) -> Date
        require n >= -730_000_000 and n <= 730_000_000
        require days_from_civil(self.year, self.month, self.day) + n >= -365_000_000
        require days_from_civil(self.year, self.month, self.day) + n <= 364_000_000
        example Date(year: 2024, month: 2, day: 28).add_days(1) == Date(year: 2024, month: 2, day: 29)
        example Date(year: 2026, month: 1, day: 1).add_days(-1) == Date(year: 2025, month: 12, day: 31)
    { … }

    /// The date `n` months later (or earlier): the same day, or the
    /// month's last when it is shorter (January 31 and one month is
    /// February 28 or 29).
    pub fn add_months(self, n: Int) -> Date
        require n >= -24_000_000 and n <= 24_000_000
        require self.year * 12 + n >= -11_990_000 and self.year * 12 + n <= 11_990_000
        example Date(year: 2024, month: 1, day: 31).add_months(1) == Date(year: 2024, month: 2, day: 29)
        example Date(year: 2026, month: 3, day: 15).add_months(-3) == Date(year: 2025, month: 12, day: 15)
    { … }

    /// How many days from this date to `other`: negative when `other`
    /// comes first.
    pub fn days_until(self, other: Date) -> Int
        example Date(year: 2024, month: 1, day: 1).days_until(Date(year: 2025, month: 1, day: 1)) == 366
        example Date(year: 2026, month: 1, day: 2).days_until(Date(year: 2026, month: 1, day: 1)) == -1
    { … }

    /// `2026-11-04`, as ISO 8601 writes it.
    pub fn iso(self) -> String
        example Date(year: 2026, month: 11, day: 4).iso() == "2026-11-04"
    { … }
}

/// A time of day, with no date and no zone.
pub type Time {
    pub hour: Int
    pub minute: Int
    pub second: Int
    pub ms: Int

    invariant hour >= 0 and hour <= 23
    invariant minute >= 0 and minute <= 59
    invariant second >= 0 and second <= 59
    invariant ms >= 0 and ms <= 999

    /// `09:05:30`, with `.250` when there are milliseconds.
    pub fn iso(self) -> String
        example Time(hour: 9, minute: 5, second: 30, ms: 0).iso() == "09:05:30"
        example Time(hour: 23, minute: 0, second: 0, ms: 250).iso() == "23:00:00.250"
    { … }
}

/// A date and a time of day, with no zone: what a wall clock and a
/// calendar show. A moment is a number of milliseconds (`time.now_ms()`);
/// `time.utc` turns one into this, as it is in UTC.
pub type DateTime {
    pub date: Date
    pub time: Time

    /// `2026-11-04T09:05:30`.
    pub fn iso(self) -> String
        example utc(1_762_247_130_000).iso() == "2025-11-04T09:05:30"
    { … }

    /// The moment this is in UTC, in milliseconds since 1970-01-01 UTC.
    pub fn utc_ms(self) -> Int
        example utc(1_762_247_130_250).utc_ms() == 1_762_247_130_250
        example utc(-1).utc_ms() == -1
    { … }
}

/// Why a name isn't a time zone.
pub type ZoneError = UnknownZone(name: String)

/// Which moments show a date and time of day in a zone (spec 14.4): one,
/// none (skipped when daylight saving time began: the moments it would be
/// with the offset after and before the jump), or two (repeated when it
/// ended).
pub type Local = Exact(ms: Int) | Skipped(earlier: Int, later: Int) | Repeated(earlier: Int, later: Int)

/// A time zone of the IANA database, by name, or a fixed offset from UTC
/// (`+05:30`): what the clocks there show at each moment, daylight saving
/// time included (spec 14.4).
pub type Zone {
    pub name: String

    invariant digits.offset(name) != none or time.zone_offset(name, 0) != none

    /// How many seconds the zone is ahead of UTC at the moment `ms`.
    pub fn offset_seconds(self, ms: Int) -> Int
        example Zone(name: "Asia/Kolkata").offset_seconds(0) == 19_800
        example Zone(name: "UTC").offset_seconds(0) == 0
        example Zone(name: "-08:00").offset_seconds(0) == -28_800
    { … }

    /// The date and time of day the clocks in the zone show at `ms`.
    pub fn at(self, ms: Int) -> DateTime
        require ms >= -30_000_000_000_000_000 and ms <= 30_000_000_000_000_000
        example Zone(name: "Asia/Kolkata").at(0).iso() == "1970-01-01T05:30:00"
    { … }

    /// The moment `ms` as the clocks in the zone show it, with the offset:
    /// `2026-11-04T14:35:30+05:30`, and `Z` for an offset of zero.
    pub fn iso(self, ms: Int) -> String
        require ms >= -30_000_000_000_000_000 and ms <= 30_000_000_000_000_000
        example Zone(name: "+05:30").iso(0) == "1970-01-01T05:30:00+05:30"
        example Zone(name: "-08:00").iso(0) == "1969-12-31T16:00:00-08:00"
        example Zone(name: "UTC").iso(0) == "1970-01-01T00:00:00Z"
    { … }

    /// Which moments the clocks in the zone show `dt`.
    pub fn resolve(self, dt: DateTime) -> Local
        require dt.date.year >= -100_000 and dt.date.year <= 100_000
        example Zone(name: "UTC").resolve(utc(0)) == Local.Exact(ms: 0)
    { … }

    /// The moment the clocks in the zone show `dt`: a skipped time moves
    /// later by the gap, a repeated one is its earlier moment (RFC 5545,
    /// as `java.time` and `jiff` do).
    pub fn moment(self, dt: DateTime) -> Int
        require dt.date.year >= -100_000 and dt.date.year <= 100_000
        example Zone(name: "Asia/Kolkata").moment(utc(19_800_000)) == 0
    { … }
}

/// The time zone named `name` in the IANA database (`Asia/Kolkata`,
/// `Europe/Berlin`, `UTC`), or the fixed offset `+05:30`.
pub fn zone(name: String) -> Zone ! ZoneError
    example zone("Asia/Kolkata") == Zone(name: "Asia/Kolkata")
    example zone("+05:30") == Zone(name: "+05:30")
    example zone("Mars/Olympus") fails ZoneError.UnknownZone(name: "Mars/Olympus")
    example zone("+24:00") fails ZoneError.UnknownZone(name: "+24:00")
{ … }

/// Whether `year` has a February 29.
pub fn is_leap_year(year: Int) -> Bool
    example is_leap_year(2024)
    example not is_leap_year(1900)
    example is_leap_year(2000)
    example not is_leap_year(2026)
{ … }

/// How many days month `month` (1 to 12) of `year` has.
pub fn days_in_month(year: Int, month: Int) -> Int
    require month >= 1 and month <= 12
    example days_in_month(2024, 2) == 29
    example days_in_month(2026, 2) == 28
    example days_in_month(2026, 4) == 30
    example days_in_month(2026, 12) == 31
{ … }

/// The date and time of day the moment `ms` (since 1970-01-01 UTC) is in
/// UTC.
pub fn utc(ms: Int) -> DateTime
    require ms >= -31_000_000_000_000_000 and ms <= 31_000_000_000_000_000
    example utc(0).iso() == "1970-01-01T00:00:00"
    example utc(1_762_247_130_250).iso() == "2025-11-04T09:05:30.250"
    example utc(-1).iso() == "1969-12-31T23:59:59.999"
{ … }

/// Today's date in UTC.
pub fn today() -> Date { … }

/// The date and time of day now, in UTC.
pub fn now() -> DateTime { … }

/// The date `text` writes as ISO 8601 does: `2026-11-04`. A year before
/// 0 or after 9999 has a sign or more digits, as `iso` writes it:
/// `-0005-01-01`, `12345-06-07`, `+12345-06-07`.
pub fn parse_date(text: String) -> Date ! DateError
    example parse_date("2026-11-04") == Date(year: 2026, month: 11, day: 4)
    example parse_date("-0005-01-01") == Date(year: -5, month: 1, day: 1)
    example parse_date("+12345-06-07") == Date(year: 12_345, month: 6, day: 7)
    example parse_date("2026-02-30") fails DateError.Invalid(text: "2026-02-30")
    example parse_date("4 Nov 2026") fails DateError.Invalid(text: "4 Nov 2026")
    example parse_date("2026-+1-04") fails DateError.Invalid(text: "2026-+1-04")
    example parse_date("026-01-01") fails DateError.Invalid(text: "026-01-01")
    example parse_date("2000000-01-01") fails DateError.Invalid(text: "2000000-01-01")
{ … }

/// The time of day `text` writes: `09:05`, `09:05:30`, `09:05:30.250`.
pub fn parse_time(text: String) -> Time ! DateError
    example parse_time("09:05") == Time(hour: 9, minute: 5, second: 0, ms: 0)
    example parse_time("09:05:30.25") == Time(hour: 9, minute: 5, second: 30, ms: 250)
    example parse_time("09:05:30.1239") == Time(hour: 9, minute: 5, second: 30, ms: 123)
    example parse_time("24:00") fails DateError.Invalid(text: "24:00")
    example parse_time("9:05") fails DateError.Invalid(text: "9:05")
    example parse_time("09:05.5") fails DateError.Invalid(text: "09:05.5")
{ … }

/// The date and time of day `text` writes, with no zone:
/// `2026-11-04T09:05:30`.
pub fn parse_datetime(text: String) -> DateTime ! DateError
    example parse_datetime("2026-11-04T09:05").iso() == "2026-11-04T09:05:00"
    example parse_datetime("2026-11-04T09:05:30Z") fails DateError.Invalid(text: "2026-11-04T09:05:30Z")
    example parse_datetime("2026-11-04") fails DateError.Invalid(text: "2026-11-04")
{ … }

/// The moment `text` writes, which must say its offset from UTC:
/// `2026-11-04T09:05:30Z`, `2026-11-04T14:35:30+05:30`.
pub fn parse_moment(text: String) -> Int ! DateError
    example parse_moment("1970-01-01T05:30:00+05:30") == 0
    example parse_moment("1969-12-31T16:00:00-08:00") == 0
    example parse_moment("1970-01-01T00:00:00.250Z") == 250
    example parse_moment("1970-01-01T00:00:00") fails DateError.Invalid(text: "1970-01-01T00:00:00")
{ … }

/// The time of day `text` writes, if it writes one.
fn time_of(text: String) -> Time? { … }

/// Days since 1970-01-01 of a date (Howard Hinnant's `days_from_civil`).
fn days_from_civil(year: Int, month: Int, day: Int) -> Int
    require year >= -1_000_000 and year <= 1_000_000
    require month >= 1 and month <= 12
    require day >= 1 and day <= 31
    example days_from_civil(1970, 1, 1) == 0
    example days_from_civil(2000, 3, 1) == 11_017
    example days_from_civil(1969, 12, 31) == -1
{ … }

/// The date `days` days after 1970-01-01 (Hinnant's `civil_from_days`).
fn civil_from_days(days: Int) -> Date
    require days >= -365_000_000 and days <= 364_000_000
    example civil_from_days(0) == Date(year: 1970, month: 1, day: 1)
    example civil_from_days(11_017) == Date(year: 2000, month: 3, day: 1)
    example civil_from_days(-1) == Date(year: 1969, month: 12, day: 31)
{ … }

stdlib/vec/vec.kav:
use std.math

/// A vector of two parts.
pub type Vec2<T: Number>: Add, Sub, Neg, Mul<T>, Div<T> {
    pub x: T
    pub y: T

    fn add(self, o: Vec2<T>) -> Vec2<T> { … }
    fn sub(self, o: Vec2<T>) -> Vec2<T> { … }
    fn neg(self) -> Vec2<T> { … }
    fn mul(self, k: T) -> Vec2<T> { … }
    fn div(self, k: T) -> Vec2<T> { … }

    /// Each part times the same part of `o`.
    pub fn scale(self, o: Vec2<T>) -> Vec2<T> { … }

    /// The parts multiplied in pairs and added.
    pub fn dot(self, o: Vec2<T>) -> T { … }

    /// Its length, squared.
    pub fn length_squared(self) -> T { … }

    /// Its length.
    pub fn length(self) -> T where T: Floating { … }

    /// The same direction with length 1; length 0 stays as it is.
    pub fn normalized(self) -> Vec2<T> where T: Floating { … }

    /// How far `o` is.
    pub fn distance(self, o: Vec2<T>) -> T where T: Floating { … }

    /// The point `t` of the way to `o`.
    pub fn lerp(self, o: Vec2<T>, t: T) -> Vec2<T> where T: Floating { … }
}

/// A vector of three parts.
pub type Vec3<T: Number>: Add, Sub, Neg, Mul<T>, Div<T> {
    pub x: T
    pub y: T
    pub z: T

    fn add(self, o: Vec3<T>) -> Vec3<T> { … }
    fn sub(self, o: Vec3<T>) -> Vec3<T> { … }
    fn neg(self) -> Vec3<T> { … }
    fn mul(self, k: T) -> Vec3<T> { … }
    fn div(self, k: T) -> Vec3<T> { … }

    /// Each part times the same part of `o`.
    pub fn scale(self, o: Vec3<T>) -> Vec3<T> { … }

    /// The parts multiplied in pairs and added.
    pub fn dot(self, o: Vec3<T>) -> T { … }

    /// At right angles to both, by the right-hand rule.
    pub fn cross(self, o: Vec3<T>) -> Vec3<T> { … }

    /// Its length, squared.
    pub fn length_squared(self) -> T { … }

    /// Its length.
    pub fn length(self) -> T where T: Floating { … }

    /// The same direction with length 1; length 0 stays as it is.
    pub fn normalized(self) -> Vec3<T> where T: Floating { … }

    /// How far `o` is.
    pub fn distance(self, o: Vec3<T>) -> T where T: Floating { … }

    /// The point `t` of the way to `o`.
    pub fn lerp(self, o: Vec3<T>, t: T) -> Vec3<T> where T: Floating { … }
}

/// A vector of four parts.
pub type Vec4<T: Number>: Add, Sub, Neg, Mul<T>, Div<T> {
    pub x: T
    pub y: T
    pub z: T
    pub w: T

    fn add(self, o: Vec4<T>) -> Vec4<T> { … }
    fn sub(self, o: Vec4<T>) -> Vec4<T> { … }
    fn neg(self) -> Vec4<T> { … }
    fn mul(self, k: T) -> Vec4<T> { … }
    fn div(self, k: T) -> Vec4<T> { … }

    /// Each part times the same part of `o`.
    pub fn scale(self, o: Vec4<T>) -> Vec4<T> { … }

    /// The parts multiplied in pairs and added.
    pub fn dot(self, o: Vec4<T>) -> T { … }

    /// Its length, squared.
    pub fn length_squared(self) -> T { … }

    /// Its length.
    pub fn length(self) -> T where T: Floating { … }

    /// The same direction with length 1; length 0 stays as it is.
    pub fn normalized(self) -> Vec4<T> where T: Floating { … }

    /// How far `o` is.
    pub fn distance(self, o: Vec4<T>) -> T where T: Floating { … }

    /// The point `t` of the way to `o`.
    pub fn lerp(self, o: Vec4<T>, t: T) -> Vec4<T> where T: Floating { … }
}

/// A 4 × 4 matrix of four columns, as GPUs lay it out.
pub type Mat4<T: Floating>: MatMul<Vec4<T>, Vec4<T>> {
    pub c0: Vec4<T>
    pub c1: Vec4<T>
    pub c2: Vec4<T>
    pub c3: Vec4<T>

    /// `m @ v`: the vector transformed by the matrix.
    fn matmul(self, v: Vec4<T>) -> Vec4<T> { … }

    /// The matrix product: `b`, then this one.
    pub fn product(self, b: Mat4<T>) -> Mat4<T> { … }

    /// Rows and columns swapped.
    pub fn transposed(self) -> Mat4<T> { … }

    /// Its first three rows and columns: its turning and scaling.
    pub fn mat3(self) -> Mat3<T> { … }

    /// The matrix that changes nothing.
    pub fn identity() -> Mat4<T> { … }

    /// Moving by `v`.
    pub fn translation(v: Vec3<T>) -> Mat4<T> { … }

    /// Each axis scaled by its part of `v`.
    pub fn scaling(v: Vec3<T>) -> Mat4<T> { … }

    /// Turning by `a` radians around the x axis.
    pub fn rotation_x(a: T) -> Mat4<T> { … }

    /// Turning by `a` radians around the y axis.
    pub fn rotation_y(a: T) -> Mat4<T> { … }

    /// Turning by `a` radians around the z axis.
    pub fn rotation_z(a: T) -> Mat4<T> { … }

    /// A perspective projection, depth from 0 (near) to 1 (far), looking
    /// down -z.
    pub fn perspective(fov_y: T, aspect: T, near: T, far: T) -> Mat4<T> { … }

    /// A view from `eye` towards `target`, with `up` up.
    pub fn look_at(eye: Vec3<T>, target: Vec3<T>, up: Vec3<T>) -> Mat4<T> { … }

    /// The matrix with these first three rows, and `0 0 0 1` below them.
    fn of_rows(a: T, b: T, c: T, d: T, e: T, f: T, g: T, h: T, i: T, j: T, k: T, l: T) -> Mat4<T> { … }
}

/// A 3 × 3 matrix of three columns: turning and scaling without moving.
pub type Mat3<T: Floating>: MatMul<Vec3<T>, Vec3<T>> {
    pub c0: Vec3<T>
    pub c1: Vec3<T>
    pub c2: Vec3<T>

    /// `m @ v`: the vector transformed by the matrix.
    fn matmul(self, v: Vec3<T>) -> Vec3<T> { … }

    /// The matrix product: `b`, then this one.
    pub fn product(self, b: Mat3<T>) -> Mat3<T> { … }

    /// Rows and columns swapped.
    pub fn transposed(self) -> Mat3<T> { … }

    /// How much the matrix scales volume: 0 when it flattens space.
    pub fn determinant(self) -> T { … }

    /// The matrix that undoes this one, or `none` when it flattens space.
    pub fn inverse(self) -> Mat3<T>? { … }

    /// The matrix that changes nothing.
    pub fn identity() -> Mat3<T> { … }

    /// Each axis scaled by its part of `v`.
    pub fn scaling(v: Vec3<T>) -> Mat3<T> { … }

    /// Turning by `a` radians around the x axis.
    pub fn rotation_x(a: T) -> Mat3<T> { … }

    /// Turning by `a` radians around the y axis.
    pub fn rotation_y(a: T) -> Mat3<T> { … }

    /// Turning by `a` radians around the z axis.
    pub fn rotation_z(a: T) -> Mat3<T> { … }

    /// The matrix with these rows.
    fn of_rows(a: T, b: T, c: T, d: T, e: T, f: T, g: T, h: T, i: T) -> Mat3<T> { … }
}

/// A rotation, as a quaternion.
pub type Quat<T: Floating>: Mul {
    pub x: T
    pub y: T
    pub z: T
    pub w: T

    /// `a * b`: `b`, then `a`.
    fn mul(self, b: Quat<T>) -> Quat<T> { … }

    /// No rotation.
    pub fn identity() -> Quat<T> { … }

    /// Turning by `angle` radians around `axis`.
    pub fn around(axis: Vec3<T>, angle: T) -> Quat<T> { … }

    /// `v` turned by this rotation.
    pub fn rotate(self, v: Vec3<T>) -> Vec3<T> { … }

    /// Length 1, as rounding can drift it.
    pub fn normalized(self) -> Quat<T> { … }

    /// The same rotation as a matrix.
    pub fn matrix(self) -> Mat4<T> { … }
}

stdlib/window/window.kav:
use std.input

use std.window

/// Why a window couldn't be opened: the system shows no windows here, as
/// on a server with no screen.
pub type WindowError = Unavailable(reason: String)

/// Something that happened to a window, or to a gamepad (spec 14.26).
/// From `Key` on, they come only after `listen_input()`.
pub type Event = Closed | Resized(width: Int, height: Int) | Scaled(factor: Float) | Focused(on: Bool) | Key(key: String, down: Bool) | Text(text: String) | MouseMoved(x: Float, y: Float) | MouseButton(button: Int, down: Bool) | Wheel(x: Float, y: Float) | Motion(x: Float, y: Float) | PadConnected(pad: Int, name: String) | PadGone(pad: Int) | PadButton(pad: Int, button: String, down: Bool) | PadAxis(pad: Int, axis: String, value: Float) | Touch(id: Int, x: Float, y: Float, phase: String, pressure: Float)

/// An open window. It closes when its last holder ends, or at `close()`.
pub type AppWindow: Drop {
    id: Int

    /// The events that came, waiting for at least one; none once the
    /// window is closed.
    pub fn events(self) -> [Event] uses Window { … }

    /// The events that came, without waiting.
    pub fn poll(self) -> [Event] uses Window { … }

    /// Calls `f` with each event as it comes, until `f` gives `false` or
    /// the window is closed.
    pub fn run(self, f: fn(Event) -> Bool) uses Window { … }

    /// From now on, keyboard, mouse, text and gamepad events come too.
    pub fn listen_input(self) uses Input { … }

    /// The inside of the window, in pixels.
    pub fn size(self) -> (width: Int, height: Int) uses Window { … }

    /// How many pixels make one point on this screen.
    pub fn scale(self) -> Float uses Window { … }

    /// Changes the title.
    pub fn set_title(self, title: String) uses Window { … }

    /// Fills the screen the window is on, or leaves it.
    pub fn set_fullscreen(self, on: Bool) uses Window { … }

    /// Hides the pointer and keeps it in the window; `Motion` events
    /// still come.
    pub fn lock_cursor(self, on: Bool) uses Input { … }

    /// The window's number, which `std.gpu` draws into it by.
    pub fn number(self) -> Int { … }

    /// Closes the window; closing it again does nothing.
    pub fn close(self) uses Window { … }

    fn drop(self) uses Window { … }
}

/// A window of `width` × `height` pixels titled `title`, shown at once.
pub fn open(title: String, width: Int, height: Int) -> AppWindow ! WindowError uses Window
    require width >= 1 and height >= 1
{ … }

/// The runtime's events, three numbers each, as `Event`s; texts holds
/// each one's key or typed text.
fn decoded(id: Int, numbers: [Float]) -> [Event] uses Window { … }

/// A touch at `x`, `y` from its text: its phase, id and pressure, as
/// `Began 3 0.5`.
fn touch_of(x: Float, y: Float, text: String) -> Event
    example touch_of(1.0, 2.0, "Moved 7 0.25") == Event.Touch(id: 7, x: 1.0, y: 2.0, phase: "Moved", pressure: 0.25)
{ … }

/// One event from its kind's number (as `Event`'s variants are
/// numbered), two numbers and a text.
fn event_of(kind: Int, a: Float, b: Float, text: String) -> Event
    require a.abs() <= 1e15 and b.abs() <= 1e15
    example event_of(1, 640.0, 480.0, "") == Event.Resized(width: 640, height: 480)
    example event_of(4, 1.0, 0.0, "KeyW") == Event.Key(key: "KeyW", down: true)
    example event_of(12, 3.0, 1.0, "South") == Event.PadButton(pad: 3, button: "South", down: true)
{ … }
